<script setup>
import {ref} from 'vue'
import {api} from '../api/library.js'
import CopyButton from '../components/CopyButton.vue'
const p=defineProps({user:Object}),emit=defineEmits(['quota','logout']);const code=ref(''),busy=ref(false),msg=ref('')
async function redeem(){if(busy.value||!code.value.trim())return;busy.value=true;try{const d=await api('/card/redeem',{code:code.value.trim()});emit('quota',d.quota);code.value='';msg.value=`已增加 ${d.added} 次下载次数。`}catch(e){msg.value=e.message}finally{busy.value=false}}
async function logout(){if(busy.value)return;busy.value=true;try{await api('/auth/logout',{});emit('logout')}catch(e){msg.value=e.message}finally{busy.value=false}}
</script><template><section><h1>我的<em>账户</em></h1><div class="panel"><h2>{{p.user.username}}</h2><p>{{p.user.is_admin?'管理员不消耗下载次数':`剩余 ${p.user.download_quota} 次下载额度`}}</p><form v-if="!p.user.is_admin" class="searchbox" @submit.prevent="redeem"><input v-model="code" aria-label="卡密" placeholder="输入卡密"><button :disabled="busy" class="primary">兑换</button></form><div class="row"><a href="https://wzyp.cn/shop/N0CQ5T2I" target="_blank" rel="noopener">购买卡密 ↗</a><a href="https://www.ldxp.cn/order" target="_blank" rel="noopener">查询订单 ↗</a></div></div><details class="contact"><summary>联系管理员</summary><p class="contact-note">添加好友时请备注「小说下载」。</p><dl><div v-for="c in [{channel:'QQ',id:'3637438435'},{channel:'微信',id:'acimer'}]" :key="c.channel" class="contact-row"><dt>{{c.channel}}</dt><dd>{{c.id}}</dd><dd class="copy-action"><CopyButton :text="c.id" :label="'复制 '+c.channel"/></dd></div></dl></details><button :disabled="busy" @click="logout">退出登录</button><p role="status">{{msg}}</p></section></template>
<style scoped>
.contact summary{font-weight:600}.contact-note{font-size:13px;color:var(--muted);margin:0 0 6px}.contact dl{margin:0}.contact-row{display:grid;grid-template-columns:3em minmax(0,1fr) auto;align-items:center;gap:8px;border-top:1px solid var(--line);padding:4px 0}.contact-row dt{color:var(--muted)}.contact-row dd{margin:0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.copy-action{display:grid;justify-items:end}.copy-action :deep(button){color:var(--accent);background:none;border:0;padding:0 6px}.copy-action :deep(small:empty){display:none}
</style>
